// Seed batch anna-cjis-2026-10-20 from Anna_CJIS-Tracker_noPII-BJ.xlsx (LAN Import folder).
// The workbook stays outside this repository. DOB/SSN were not in the source headers.
// Raw State / Driver's License Number column was excluded (DEC-020).
// Existing localStorage records are replaced once when this batch id is new.

const TEST_APPLICANT_SEED_BATCH = "anna-cjis-2026-10-20";

function getTestApplicantSeed() {
  return TEST_APPLICANT_RECORDS.map((record) => ({
    ...record,
    documents: Array.isArray(record.documents) ? record.documents.slice() : [],
  }));
}

function getLimitedViewApplicantSeed() {
  return TEST_APPLICANT_RECORDS.filter((record) => record.clearanceType === "One Time Visit").map((record) => ({
    ...record,
    documents: Array.isArray(record.documents) ? record.documents.slice() : [],
  }));
}

